        count[type]++;
    }

    vector<vector<vector<vector<int>>>> dp(2,
        vector<vector<vector<int>>>(count[0] + 1,
            vector<vector<int>>(count[1] + 1,
                vector<int>(count[2] + 1, INT_MAX / 2)
